class Solution {
    public int[] frequencySort(int[] nums) {
        int n = nums.length;
        Integer[] a = new Integer[n];
        int[] freq = new int[201];
        for (int i = 0; i < n; i++) {
            a[i] = nums[i];
            int c = 0;
            for (int x : nums) if (x == nums[i]) c++;
            freq[nums[i] + 100] = c;
        }
        Arrays.sort(a, (x, y) -> freq[x + 100] != freq[y + 100] ? freq[x + 100] - freq[y + 100] : y - x);
        for (int i = 0; i < n; i++) nums[i] = a[i];
        return nums;
    }
}

